local OverseaManageCardHeadNode = Class('OverseaManageCardHeadNode')
local CardHeadNodePath = "Game.Behaviours.CardHeadNode"
local MaidCoffeeUtils     = import("Game.MaidCoffee.MaidCoffeeUtils")
function OverseaManageCardHeadNode:__init()

